#include<bits/stdc++.h>
using namespace std;

int main(){
	// 入力を受け取る
	int n;
	cin >> n;

	vector<string> c(n);
	for (int i=0; i<n; i++){
		cin >> c[i];
	}

	// 各人についての勝ち数を求める
	vector<int> wins(n);
	for (int i=0; i<n; i++){
		for (int j=0; j<n; j++){
			if (c[i][j] == 'o'){
				wins[i] += 1;
			}
		}
	}

	// 勝ち数は, 0 以上 n-1 以下の整数しか取りえない
	// bucket[i] は勝ち数 i の番号をすべて入れる
	vector bucket(n, vector<int>(0));
	for (int i=0; i<n; i++){
		bucket[wins[i]].push_back(i);
	}

	// さきほど, 番号の小さい順に bucket に入れたので,
	// bucket[i] の中身は, すでに番号の小さい順になっている.
	// 勝ち数の多い方から, bucket[i] の中身を出力していけばよい
	for (int i=n-1; i>=0; i--){
		for (int j: bucket[i]){
			cout << j+1 << ' ';
		}
	}
	cout << '\n';
}
